    // ── Ventana de venta (TicketSalesWindowField, FR-013) ──
    // `{when}` y los `{opens}`/`{closes}` de los resúmenes llegan ya
    // formateados en la zona horaria del EVENTO y con su abreviatura ("vie, 9
    // oct, 10:00 a. m. CDT"). Nunca uses un formato de fecha ICU aquí: se
    // formatearía en la zona de quien lee y anularía la única comprobación que
    // puede hacer quien organiza.
    ttWindowToggle: "Limita cuándo se vende esta entrada",
    // Breve, porque aparece bajo una casilla sin marcar en el caso habitual.
    // Tiene que dejar claro algo que las etiquetas no dicen: cada campo por
    // separado ya es una configuración completa.
    ttWindowHelp: "Indica una hora de apertura, una de cierre o ambas.",
    ttWindowOpensAt: "A la venta desde",
    ttWindowClosesAt: "Deja de venderse",
    ttWindowOpensReadback: "Se abre el {when}",
    ttWindowClosesReadback: "Se cierra el {when}",
    // El límite es semiabierto, explicado en lenguaje corriente: `salesCloseAt`
    // es EXCLUSIVO, y de ahí depende que un par anticipada/taquilla se
    // encadene sin hueco ni solapamiento.
    ttWindowBoundaryNote:
      "La venta se detiene justo al llegar la hora de cierre: si pones las 18:00, la última venta es a las 17:59. Otra entrada que se abra a las 18:00 toma el relevo sin hueco ni solapamiento.",
    ttWindowZoneNote: "Las horas son las del evento ({timeZone}).",
    ttWindowTimezonePending:
      "Cargando la zona horaria del evento: no se puede fijar la ventana de venta hasta que llegue.",
    ttWindowInvalidTitle: "Revisa la ventana de venta",
    // DOS mensajes, no uno: son dos errores distintos con soluciones distintas,
    // y un único texto que describía ambos resultaba FALSO en uno de los dos
    // casos. El texto anterior ("…Una entrada que se abre y se cierra en el
    // mismo momento…") se mostraba con un par INVERTIDO y le decía a quien
    // organiza que había puesto el mismo momento dos veces, cosa que no había
    // hecho. `classifySalesWindowOrder` los distingue; el texto ahora también.
    //
    // Ambos se muestran en línea mientras se escribe y en el aviso al guardar,
    // así que la redacción tiene que servir en los dos sitios.
    ttWindowOrderMessage:
      "Esta entrada dejaría de venderse antes de abrirse. La hora de apertura tiene que ser anterior a la de cierre.",
    // Con un cierre EXCLUSIVO, "el mismo momento" es una ventana vacía: la
    // entrada parecería configurada y no vendería ni una sola.
    ttWindowZeroWidthMessage:
      "Esta entrada se abre y se cierra en el mismo momento, así que no podría venderse nunca. Retrasa la hora de cierre.",
    ttWindowEmptyMessage:
      "Elige cuándo se abre esta entrada, cuándo deja de venderse o ambas cosas, o desactiva “Limita cuándo se vende esta entrada”.",
    ttWindowOpenInvalidMessage:
      "No se pudo leer esa fecha y hora de apertura. Vuelve a elegirla.",
    ttWindowCloseInvalidMessage:
      "No se pudo leer esa fecha y hora de cierre. Vuelve a elegirla.",
    // Resúmenes de la lista de entradas. Cuatro claves en vez de una armada por
