    ttWindowSummaryRange: "A la venta del {opens} al {closes}",
    ttWindowSummaryFrom: "A la venta desde el {opens}",
    ttWindowSummaryUntil: "A la venta hasta el {closes}",
    ttWindowSummaryEnded: "La venta terminó el {closes}",

